  const history = entries.length ? entries.slice(0, 12).map((entry) => `<article class="journal-entry"><div><b>${formatJournalDate(entry.date)}</b><span>${entry.date === today ? '今天' : ''} <button class="entry-delete" type="button" data-delete-date="${entry.date}" aria-label="删除${formatJournalDate(entry.date)}记录">删除</button></span></div><div class="entry-metrics"><span>${lensByKey(entry.lens).label}</span><span>${escapeHtml(entry.context || '其他')}</span><span>情绪 ${escapeHtml(entry.mood || '平静')}</span><span>精力 ${entry.energy || 3}/5</span><span>专注 ${entry.focus || 3}/5</span><span>${entry.done ? '已完成' : '进行中'}</span></div><p><strong>${escapeHtml(entry.intention || '没有写下行动')}</strong><br/>${escapeHtml(entry.note || '没有补充文字。')}</p><p class="entry-secondary"><span><b>感受</b> ${escapeHtml(entry.felt || '未填写')}</span><span><b>下一步</b> ${escapeHtml(entry.nextAction || '未填写')}</span></p></article>`).join('') : `<div class="empty-state"><strong>还没有观象记录</strong><p>今天先写下一句事实。连续几天后，你会看到自己的节奏，而不是等待一条预言。</p></div>`
  const lensOptions = observationLenses.map((item) => `<option value="${item.key}" ${item.key === (todayEntry.lens || profile.dominant.key) ? 'selected' : ''}>${item.label}</option>`).join('')
  const contextOptions = journalContexts.map((item) => `<option value="${item}" ${item === (todayEntry.context || '其他') ? 'selected' : ''}>${item}</option>`).join('')
  const compareOptions = entries.map((item) => '<option value="' + item.date + '">' + formatJournalDate(item.date) + '</option>').join('')
  shell(`<main class="workspace-page journal-page"><section class="workspace-heading"><div><p class="eyebrow">记 · LOCAL OBSERVATION LOG</p><h2>把一天留下来，<br/><em>让变化可见。</em></h2><p>观象日志是璇玑的实际使用核心：用三个简单刻度和一段文字记录当下，按日期回看自己的节奏。它只保存到这台电脑，不替你解释人生。</p></div><div class="heading-stat"><strong>${entries.length}</strong><span>条本地记录</span></div></section><section class="journal-layout"><form class="detail-card journal-form" id="journal-form"><div class="card-kicker">编辑观象 <span>本地时间线</span></div><div class="prompt-card"><span class="prompt-mark">◇</span><p>${journalPrompt()}</p><small>提示只用于引导记录，不从日志推断结论。</small></div><label>记录日期 <small>可以补写过去</small><input id="journal-date" type="date" min="1900-01-01" max="${today}" value="${todayEntry.date}"/></label><label>观察镜头<select id="journal-lens">${lensOptions}</select></label><label>记录场景<select id="journal-context">${contextOptions}</select></label><label>今天想推进的一件事<input id="journal-intention" maxlength="120" value="${escapeHtml(todayEntry.intention || '')}" placeholder="例如：完成提案的第一版结构"/></label><div class="metric-grid"><label>情绪<select id="journal-mood"><option value="清醒" ${todayEntry.mood === '清醒' ? 'selected' : ''}>清醒</option><option value="好奇" ${todayEntry.mood === '好奇' ? 'selected' : ''}>好奇</option><option value="平静" ${!todayEntry.mood || todayEntry.mood === '平静' ? 'selected' : ''}>平静</option><option value="疲惫" ${todayEntry.mood === '疲惫' ? 'selected' : ''}>疲惫</option><option value="混乱" ${todayEntry.mood === '混乱' ? 'selected' : ''}>混乱</option></select></label><label>精力<select id="journal-energy">${valueOptions(todayEntry.energy)}</select></label><label>专注<select id="journal-focus">${valueOptions(todayEntry.focus)}</select></label></div><label>今天发生了什么？ <small>最多 500 字</small><textarea id="journal-note" rows="6" maxlength="800" placeholder="写一个事实：哪一步完成了？发生了什么？">${escapeHtml(todayEntry.note || '')}</textarea><label>我当时怎么感受？ <small>可选</small><textarea id="journal-felt" rows="3" maxlength="300" placeholder="例如：开始时分心，后来逐渐稳定。">${escapeHtml(todayEntry.felt || "")}</textarea><label>接下来想试什么？ <small>可选</small><input id="journal-next-action" maxlength="300" value="${escapeHtml(todayEntry.nextAction || "")}" placeholder="例如：下次先关掉消息通知"/></label><label class="check-row"><input id="journal-done" type="checkbox" ${todayEntry.done ? 'checked' : ''}/><span>这件事已经完成</span></label><p class="form-error" id="journal-error" role="alert" aria-live="polite"></p><button class="primary-button wide" type="submit">保存这一天 <span>↗</span></button></form><section class="detail-card journal-history"><div class="history-head"><div><div class="card-kicker">回看时间线 <span>最近 12 条</span></div><h3>你的节奏正在形成</h3></div><div class="history-actions"><button class="ghost-button" type="button" data-action="export-journal">导出 JSON</button><button class="ghost-button" type="button" data-action="import-journal">导入备份</button><input id="journal-import" type="file" accept=".json,application/json" hidden/><span id="journal-import-status" role="status" aria-live="polite"></span></div></div><div class="compare-toolbar"><span>选择两条记录，只比较你写下的字段。</span><select id="compare-left" aria-label="第一条对照记录">${compareOptions}</select><select id="compare-right" aria-label="第二条对照记录">${compareOptions}</select><button class="ghost-button" id="start-compare" type="button">开始对照</button><p class="form-help" id="compare-help" role="status" aria-live="polite">${entries.length < 2 ? '再保存一条不同日期的记录后才能开始对照。' : ''}</p></div><div class="journal-list">${history}</div></section></section></main>`)
  if (undoJournal) { const banner = document.createElement('div'); banner.className = 'undo-banner'; banner.setAttribute('role', 'status'); banner.innerHTML = `已删除 ${formatJournalDate(undoJournal.entry.date)} 记录。<button class="text-button" data-action="undo-delete">撤销</button>`; document.querySelector('.journal-page')?.prepend(banner) }
  const dateInput = document.querySelector('#journal-date')
  const loadDate = () => { const entry = readJournal().find((item) => item.date === dateInput.value) || { mood: '平静', energy: 3, focus: 3, lens: profile.dominant.key, intention: '', note: '', done: false }; document.querySelector('#journal-lens').value = entry.lens || profile.dominant.key; document.querySelector('#journal-context').value = entry.context || '其他'; document.querySelector('#journal-mood').value = entry.mood || '平静'; document.querySelector('#journal-energy').value = entry.energy || 3; document.querySelector('#journal-focus').value = entry.focus || 3; document.querySelector('#journal-intention').value = entry.intention || ''; document.querySelector('#journal-note').value = entry.note || ''; document.querySelector('#journal-felt').value = entry.felt || ''; document.querySelector('#journal-next-action').value = entry.nextAction || ''; document.querySelector('#journal-done').checked = Boolean(entry.done) }
  dateInput.onchange = loadDate
  document.querySelector('#journal-form').onsubmit = (event) => { event.preventDefault(); const date = dateInput.value; const intention = document.querySelector('#journal-intention').value.trim(); const error = document.querySelector('#journal-error'); if (!date) { error.textContent = '请选择记录日期'; return } if (!intention) { error.textContent = '请先写下这一天想推进的一件事'; return } saveObservation({ date, lens: document.querySelector('#journal-lens').value, context: document.querySelector('#journal-context').value, mood: document.querySelector('#journal-mood').value, energy: Number(document.querySelector('#journal-energy').value), focus: Number(document.querySelector('#journal-focus').value), intention, note: document.querySelector('#journal-note').value.trim(), felt: document.querySelector('#journal-felt').value.trim(), nextAction: document.querySelector('#journal-next-action').value.trim(), done: document.querySelector('#journal-done').checked }); render() }
  document.querySelector('[data-action="export-journal"]').onclick = journalExport
  const importInput = document.querySelector('#journal-import'); document.querySelector('[data-action="import-journal"]').onclick = () => importInput.click(); importInput.onchange = () => { if (importInput.files?.[0]) journalImport(importInput.files[0], (message) => { document.querySelector('#journal-import-status').textContent = message; if (message.startsWith('已导入')) setTimeout(() => render(), 600) }) }
  document.querySelectorAll('[data-delete-date]').forEach((button) => { button.onclick = () => { if (!window.confirm('删除这条本地记录？建议先导出备份。')) return; const current = readJournal(); const index = current.findIndex((entry) => entry.date === button.dataset.deleteDate); const entry = index >= 0 ? current[index] : null; if (!entry) return; writeJournal(removeJournalEntry(current, entry.date)); if (undoTimer) clearTimeout(undoTimer); undoJournal = { entry, index }; undoTimer = setTimeout(() => { undoJournal = null; undoTimer = null }, 5000); render() } })
  document.querySelector('[data-action="undo-delete"]')?.addEventListener('click', () => { if (!undoJournal) return; if (!readJournal().some((item) => item.date === undoJournal.entry.date)) writeJournal([...readJournal(), undoJournal.entry]); undoJournal = null; if (undoTimer) clearTimeout(undoTimer); undoTimer = null; render() })
  document.querySelector('#start-compare')?.addEventListener('click', () => { const left = document.querySelector('#compare-left')?.value; const right = document.querySelector('#compare-right')?.value; if (!left || !right || left === right) { const help = document.querySelector('#compare-help'); if (help) help.textContent = '请选择两条不同日期的记录。'; return } compareDates = [left, right]; screen = 'compare'; render() })
