function compare() {
  if (!profile) { screen = 'input'; render(); return }
  const records = compareDates.map((date) => readJournal().find((entry) => entry.date === date)).filter(Boolean)
  if (records.length < 2) { screen = 'journal'; render(); return }
  const [left, right] = records
  const safe = (value) => escapeHtml(value || '—')
  const fields = [
    ['场景', left.context, right.context],
    ['观察镜头', lensByKey(left.lens).label, lensByKey(right.lens).label],
    ['心境', left.mood, right.mood],
    ['精力', String(left.energy) + '/5', String(right.energy) + '/5'],
    ['专注', String(left.focus) + '/5', String(right.focus) + '/5'],
    ['完成状态', left.done ? '已完成' : '进行中', right.done ? '已完成' : '进行中'],
  ]
  const differences = fields.filter(([, a, b]) => String(a) !== String(b))
  const differenceHtml = differences.length ? differences.map(([label, a, b]) => '<div class="difference-row"><b>' + label + '</b><span>' + safe(a) + '</span><span>' + safe(b) + '</span></div>').join('') : '<p class="empty-state">这两条记录的刻度相同。可以在下面写下你自己注意到的细节。</p>'
  const recordCard = (entry, side) => '<article class="compare-card"><div class="card-kicker">' + side + ' · ' + formatJournalDate(entry.date) + ' <span>' + safe(entry.context) + '</span></div><h3>' + safe(entry.intention) + '</h3><p><b>发生了什么</b><br/>' + safe(entry.note) + '</p><p><b>当时感受</b><br/>' + safe(entry.felt) + '</p><p><b>下一步</b><br/>' + safe(entry.nextAction) + '</p><small>底色主色：' + safe(entry.profileSnapshot?.dominantLabel || profile.dominant.label) + '。这是当次记录的资料摘要，不代表事件因果。</small></article>'
  shell('<main class="workspace-page compare-page"><section class="workspace-heading"><div><p class="eyebrow">对 · TWO RECORDS</p><h2>把两天放在一起，<br/><em>只看你写下的不同。</em></h2><p>对照页不判断哪一天更好，也不把盘面和事件连成因果。它只帮你重新看见自己的文字、刻度和下一步。</p></div><div class="heading-actions"><button class="ghost-button" data-screen="journal">← 返回日志</button></div></section><section class="compare-cards">' + recordCard(left, '左侧') + recordCard(right, '右侧') + '</section><section class="detail-card difference-card"><div class="card-kicker">字段差异 <span>只做事实比较</span></div><div class="difference-table"><div class="difference-head"><span>字段</span><span>' + formatJournalDate(left.date) + '</span><span>' + formatJournalDate(right.date) + '</span></div>' + differenceHtml + '</div><label>我注意到的不同 <small>只保存到当前页面，可复制带走</small><textarea id="comparison-note" rows="5" maxlength="800" placeholder="例如：两天都选择了收束，但今天的下一步写得更具体。"></textarea></label><div class="compare-actions"><button class="primary-button" id="copy-comparison" type="button">复制对照摘要 <span>↗</span></button><button class="ghost-button" data-screen="journal">继续编辑日志</button></div><p class="form-help" id="comparison-status" role="status" aria-live="polite">这是自我观察工具，不是预测或诊断。</p></section></main>')
  document.querySelector('#copy-comparison').onclick = async () => {
    const note = document.querySelector('#comparison-note').value.trim()
    const text = '璇玑记录对照\n' + formatJournalDate(left.date) + '：' + left.intention + '\n' + formatJournalDate(right.date) + '：' + right.intention + '\n我注意到：' + (note || '（未补充）') + '\n仅比较用户记录，不构成因果或现实建议。'
    try { await navigator.clipboard.writeText(text); document.querySelector('#comparison-status').textContent = '已复制对照摘要。' } catch { document.querySelector('#comparison-status').textContent = '剪贴板不可用，请手动复制页面文字。' }
  }
}
function review() {
  if (!profile) { screen = 'input'; render(); return }
  const all = readJournal().sort((a, b) => b.date.localeCompare(a.date)); const since = new Date(); since.setDate(since.getDate() - 6); const start = `${since.getFullYear()}-${String(since.getMonth() + 1).padStart(2, '0')}-${String(since.getDate()).padStart(2, '0')}`; const entries = all.filter((item) => item.date >= start); const average = (key) => entries.length ? (entries.reduce((sum, item) => sum + Number(item[key] || 0), 0) / entries.length).toFixed(1) : '—'; const done = entries.filter((item) => item.done).length; const dateSet = new Set(all.map((item) => item.date)); let streak = 0; const cursor = new Date(); while (dateSet.has(`${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, '0')}-${String(cursor.getDate()).padStart(2, '0')}`)) { streak += 1; cursor.setDate(cursor.getDate() - 1) } const lensStats = observationLenses.map((lens) => { const used = entries.filter((item) => item.lens === lens.key); return { ...lens, count: used.length, done: used.filter((item) => item.done).length } }); const maxCount = Math.max(1, ...lensStats.map((item) => item.count)); const bars = lensStats.map((item) => `<div class="lens-stat"><div><span style="color:${item.color}">${item.label}</span><b>${item.count} 次 · ${item.count ? Math.round(item.done / item.count * 100) : 0}%完成</b></div><div class="stat-bar"><span style="width:${item.count / maxCount * 100}%;background:${item.color}"></span></div></div>`).join(''); const rows = entries.length ? entries.slice(0, 7).map((item) => `<div class="review-row"><span>${formatJournalDate(item.date)}</span><span>${lensByKey(item.lens).label}</span><span>${item.energy || '—'} / ${item.focus || '—'}</span><span>${item.done ? '完成' : '未完成'}</span></div>`).join('') : `<div class="empty-state"><strong>先积累三天记录</strong><p>复盘只描述你写下的内容，不替你推断原因。完成三条记录后再回来。</p></div>`; shell(`<main class="workspace-page review-page"><section class="workspace-heading"><div><p class="eyebrow">回 · LAST 7 DAYS</p><h2>看见自己的节奏，<br/><em>不急着解释。</em></h2><p>这里的数字只是你主动记录的描述统计：记录天数、精力、专注和五行镜头使用情况。它不是预测，也不是因果分析。</p></div><div class="heading-stat"><strong>${entries.length}</strong><span>近 7 日记录</span></div></section><section class="review-grid"><section class="stat-cards"><article class="detail-card stat-card"><span>平均精力</span><strong>${average('energy')}</strong><small>/ 5</small></article><article class="detail-card stat-card"><span>平均专注</span><strong>${average('focus')}</strong><small>/ 5</small></article><article class="detail-card stat-card"><span>完成事项</span><strong>${done}</strong><small>/ ${entries.length || 0}</small></article><article class="detail-card stat-card"><span>连续记录</span><strong>${streak}</strong><small>天</small></article></section><section class="detail-card lens-review"><div class="card-kicker">工作镜头 <span>选择过的行动方式</span></div><h3>哪种方式最近出现得最多？</h3>${bars}<div class="source-note">木、火、土、金、水在这里是五种可选的工作镜头：启动、表达、承接、收束、沉淀。它们不代表你“是什么人”。</div></section><section class="detail-card weekly-table"><div class="card-kicker">最近记录 <span>${entries.length ? `${start} 起` : '等待第一条'}</span></div><div class="review-table"><div class="review-row review-head"><span>日期</span><span>镜头</span><span>精力 / 专注</span><span>状态</span></div>${rows}</div><button class="overview-link" data-screen="journal">编辑或补写记录 <span>→</span></button></section></section></main>`)
}
function radar() { const points = profile.scores.map((item, i) => { const angle = -Math.PI / 2 + Math.PI * 2 * i / 5; const radius = 34 + item.percent * .27; return `${50 + Math.cos(angle) * radius},${50 + Math.sin(angle) * radius}` }).join(' '); return `<svg class="radar" viewBox="0 0 100 100"><polygon points="${points}" class="radar-shape"/><text x="50" y="5" class="radar-label">木</text><text x="97" y="53" class="radar-label">火</text><text x="68" y="96" class="radar-label">土</text><text x="32" y="96" class="radar-label">金</text><text x="3" y="53" class="radar-label">水</text></svg>` }
function detail() { const title = selected === '命盘' ? '六字命盘' : selected === '命纹' ? '命纹印章' : selected === '星官' ? '本命星官' : selected === '性格' ? '阴阳四维' : selected === '节气' ? '生日节气' : '五行气象'; const intro = selected === '命盘' ? '三柱是出生日期在传统历法中的文化标记。时辰未知，虚位以待。' : selected === '命纹' ? '把你的输入变成一枚只属于这组数据的图腾。它是视觉演绎，不是身份判断。' : selected === '星官' ? '本命星官是二十八宿的文化对照入口。当前采用固定28日循环演示，不代表正式天文或历法定位。' : selected === '性格' ? '用四条滑条描述当下的自我感受。它是现代性格工具和阴阳话语的产品化对照，不是心理诊断。' : selected === '节气' ? '节气是观察一年时间变化的文化坐标。当前日期采用固定近似日期表，仅用于体验节令意象。' : '五行比例会影响这次体验的主色与命纹密度，用来观察，不用来给人生下结论。'; const safeName = escapeHtml(profile.name); const eyebrow = selected === '命纹' ? '铭 · 01' : selected === '星官' ? '星 · 01' : selected === '性格' ? '性 · 01' : selected === '节气' ? '星 · 02' : `命 · ${selected === '命盘' ? '01' : '02'}`; let body = ''
  if (selected === '命盘') body = `<section class="detail-card pillars-card"><div class="card-kicker">你的三柱 <span>近似节气口径</span></div><div class="pillars">${profile.pillars.map(p => `<div class="pillar"><span>${p.title}</span><strong>${p.value}</strong><small>${p.note}</small></div>`).join('')}<div class="pillar missing"><span>时柱</span><strong>··</strong><small>时辰未知，虚位以待</small></div></div><div class="source-note">当前版本使用近似节气边界和公历日序推导，只用于文化体验；正式发布前需用历法资料逐条复核。</div></section>`
  if (selected === '五行') body = `<section class="detail-card wuxing-card"><div class="card-kicker">五行气象 <span>个人主色：${profile.dominant.label}</span></div><div class="wuxing-layout">${radar()}<div class="score-list">${profile.scores.map(i => `<div class="score-row"><span class="score-name"><i style="background:${i.color}"></i>${i.label}</span><div class="score-bar"><span style="width:${i.percent * 2.5}%;background:${i.color}"></span></div><b>${i.percent}%</b></div>`).join('')}</div></div><div class="insight"><span>◈</span><p>你的盘面偏向${profile.dominant.label}。在这次文化演绎里，它象征着“${profile.dominant.hint}”。</p></div><div class="source-note">五行比例是视觉化规则，不代表科学测量，也不构成现实建议。</div></section>`
  if (selected === '星官') body = `<section class="detail-card star-card"><div class="card-kicker">二十八宿 <span>产品化循环演示</span></div><div class="star-layout"><div class="star-map"><svg viewBox="0 0 220 220" aria-label="四象星图"><circle cx="110" cy="110" r="84" fill="none" stroke="var(--accent)" stroke-opacity=".3"/><circle cx="110" cy="110" r="58" fill="none" stroke="var(--accent)" stroke-opacity=".25"/><path d="M36 110h148M110 36v148" stroke="var(--accent)" stroke-opacity=".2"/>${[...Array(7)].map((_, i) => { const angle = -Math.PI / 2 + (Math.PI * 2 * i) / 7; const x = 110 + Math.cos(angle) * 68; const y = 110 + Math.sin(angle) * 68; const active = i === profile.star.index % 7; return `<circle cx="${x}" cy="${y}" r="${active ? 5 : 2.5}" fill="${active ? 'var(--accent)' : '#9ca58d'}" opacity="${active ? 1 : .6}"/>` }).join('')}</svg><span>${profile.star.quadrant}</span></div><div class="star-copy"><p class="star-kicker">你的本命宿</p><h3>${profile.star.name}宿 · ${profile.star.animal}</h3><p>${profile.star.theme}。这句话是产品化短文，用来帮助用户观察意象，不是传统典籍原文。</p><div class="source-note">当前采用出生日期对应的28日循环作为体验口径；正式版本需要确定农历/公历对应表和来源。</div></div></div></section>`
  if (selected === '节气') body = `<section class="detail-card term-card"><div class="card-kicker">出生节令 <span>V2试验</span></div><div class="term-layout"><div class="term-orbit"><div class="term-symbol">${profile.solarTerm.name}</div><div class="term-index">${String(profile.solarTerm.index + 1).padStart(2, '0')} / 24</div></div><div class="term-copy"><p class="star-kicker">你的生日落在</p><h3>${profile.solarTerm.name}</h3><p>${profile.solarTerm.theme}。</p><div class="source-note">当前使用固定近似日期表，不代表精确节气时刻；文案为项目自写的意象演绎。</div></div></div></section>`
  if (selected === '性格') { const traits = getTraits(); const result = traitSummary(traits); body = `<section class="detail-card traits-card"><div class="card-kicker">阴阳四维 <span>V2试验</span></div><div class="traits-list">${traits.map((trait) => `<label class="trait-row"><span class="trait-label"><b>${trait.left}</b><i>${trait.key === 'motion' ? '动 / 静' : trait.key === 'shape' ? '形 / 神' : trait.key === 'reason' ? '理 / 情' : '行 / 化'}</i><b>${trait.right}</b></span><input type="range" min="0" max="100" value="${trait.value}" data-trait="${trait.key}" aria-label="${trait.left}到${trait.right}"/><span class="trait-value" data-trait-value="${trait.key}">${trait.value}%</span></label>`).join('')}</div><div class="trait-result" id="trait-summary"><b>${result.labels.join(' · ')}</b><span>${result.balanceText}。这是现代性格工具与传统阴阳话语的产品化对照。</span></div><div class="source-note">滑条结果不是MBTI测评，也不代表心理诊断。当前结果只保存到本机，之后可继续修改。</div></section>` }
  if (selected === '命纹') body = `<section class="detail-card seal-card"><div class="seal-stage"><svg viewBox="0 0 200 200" class="seal-svg"><circle cx="100" cy="100" r="78" fill="none" stroke="var(--accent)" stroke-width="1" stroke-dasharray="2 6"/><circle cx="100" cy="100" r="66" fill="var(--accent-soft)" fill-opacity=".42" stroke="var(--accent)" stroke-opacity=".5"/><polygon points="${createPattern(profile)}" fill="none" stroke="var(--accent)" stroke-width="1.4" opacity=".88"/><path d="M50 100h100M100 50v100" stroke="var(--accent)" stroke-opacity=".35"/></svg><span>${safeName}</span></div><div class="seal-copy"><div class="card-kicker">确定性图腾 <span>种子已锁定</span></div><h3>${profile.dominant.label}相生，纹样舒展。</h3><p>命纹由称呼与出生日期共同生成。同样的输入，会得到同样的图形，方便你保存、重看和分享。</p><button class="primary-button" data-action="share">生成分享卡 <span>↗</span></button><div class="source-note">这是产品化演绎，不是传统典籍中的固定结论。</div></div></section>`
  shell(`<main class="detail-page"><div class="detail-head"><button class="back-button" data-screen="pan">← 返回总盘</button><p class="eyebrow">${eyebrow}</p><h2>${title}</h2><p>${intro}</p></div>${body}</main>`); bindDetailTriggers(); if (selected === '性格') bindTraitControls() }
function info() { shell(`<main class="info-page"><div class="detail-head"><button class="back-button" data-screen="${profile ? 'today' : 'home'}">← 返回${profile ? '今日' : '首页'}</button><p class="eyebrow">说明 · 边界与隐私</p><h2>先知道它是什么，<br/><em>再开始观盘。</em></h2><p>璇玑现在同时提供个人盘面和观象日志：前者是文化资料的可视化，后者帮助你把真实生活中的观察留存下来。它不替用户做现实决定。</p></div><section class="info-grid"><article class="detail-card"><div class="card-kicker">内容边界 <span>必须读</span></div><h3>文化演绎，不是预测</h3><p>页面中的三柱、五行、颜色和命纹，用于展示传统文化符号和视觉关系。它们不代表科学测量，也不能用于判断健康、寿命、婚姻、投资或其他现实结果。</p><div class="source-note">当前三柱与五行使用近似节气边界和公历日序推导。正式版本需要确定历法口径、接入核验数据并记录来源。</div></article><article class="detail-card"><div class="card-kicker">隐私说明 <span>本地处理</span></div><h3>你的资料留在这台设备</h3><p>姓名、生日和观象日志只在本机使用 localStorage（浏览器或桌面应用的本地存储）保存。项目没有账号、后端、外部 API 或上传功能。</p><button class="ghost-button clear-data" data-action="clear-data">清除本地观盘记录</button><p class="form-help">清除会同时删除个人盘面、日志和反馈；下载到设备的文件不会被删除。</p><p class="form-help clear-status" role="status" aria-live="polite">${infoNotice}</p></article><article class="detail-card"><div class="card-kicker">数据口径 <span>原型阶段</span></div><h3>哪些内容还没有定稿</h3><ul class="info-list"><li>年柱分界和节气换月口径。</li><li>日柱算法与公开历法样本核对。</li><li>日志提示只用于自我观察，不从记录推断性格或命运。</li><li>字体、图片、音频和古籍内容的授权记录。</li></ul></article><article class="detail-card feedback-card"><div class="card-kicker">试用反馈 <span>不上传</span></div><h3>帮我判断下一步</h3><form id="feedback-form"><label>你是否理解这是文化体验？<select id="feedback-clarity"><option value="清楚">清楚</option><option value="不确定">不确定</option><option value="没理解">没理解</option></select></label><label>你愿意保存或分享吗？<select id="feedback-share"><option value="愿意">愿意</option><option value="修改后愿意">修改后愿意</option><option value="不愿意">不愿意</option></select></label><label>最困惑或最喜欢的地方 <small>选填</small><textarea id="feedback-note" rows="3" maxlength="500" placeholder="例如：我喜欢日志，但不理解月柱是什么意思"></textarea></label><button class="primary-button wide" type="submit">保存本地反馈 <span>↗</span></button><p class="form-help" id="feedback-status" role="status" aria-live="polite">反馈只保存在本机，可在保存后下载。</p></form><button class="ghost-button download-feedback" data-action="download-feedback">下载反馈JSON</button></article></section></main>`); document.querySelector('[data-action="clear-data"]').onclick = () => { localStorage.removeItem('xuanji-profile'); localStorage.removeItem('xuanji-feedback'); localStorage.removeItem('xuanji-journal-v1'); localStorage.removeItem('xuanji-journal'); infoNotice = '已清除本地观盘和反馈记录；同时已清除日志。'; profile = null; screen = 'info'; render() }; document.querySelector('#feedback-form').onsubmit = (event) => { event.preventDefault(); const feedback = { createdAt: new Date().toISOString(), clarity: document.querySelector('#feedback-clarity').value, shareIntent: document.querySelector('#feedback-share').value, note: document.querySelector('#feedback-note').value.trim() }; localStorage.setItem('xuanji-feedback', JSON.stringify(feedback)); document.querySelector('#feedback-status').textContent = '已保存到本机，可以下载反馈JSON。' }; document.querySelector('[data-action="download-feedback"]').onclick = downloadFeedback }
function downloadFeedback() { const saved = localStorage.getItem('xuanji-feedback'); if (!saved) { document.querySelector('#feedback-status').textContent = '请先保存一份反馈。'; return } const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([saved], { type: 'application/json;charset=utf-8' })); link.download = 'xuanji-feedback.json'; document.body.appendChild(link); link.click(); setTimeout(() => { URL.revokeObjectURL(link.href); link.remove() }, 1000) }
function pan() { const safeName = escapeHtml(profile.name || '未命名观者'); const journalCount = readJournal().length; shell(`<main class="workspace-page pan-page"><section class="workspace-heading dashboard-heading"><div><p class="eyebrow">观 · PERSONAL OBSERVATORY</p><h2>你好，${safeName}。<br/><em>今天想观察什么？</em></h2><p>你的数据已经落座。总览负责看见关系，日志负责把关系放回真实生活。</p></div><div class="heading-actions"><button class="primary-button" data-screen="today">开始今日观象 <span>↗</span></button><button class="ghost-button" data-action="share">生成分享卡</button></div></section><section class="metric-strip" aria-label="个人观象摘要"><article class="metric-card metric-accent"><span class="metric-label">主色气象</span><strong>${profile.dominant.label}</strong><small>${profile.dominant.hint}</small></article><article class="metric-card"><span class="metric-label">本命星官</span><strong>${profile.star.name}宿</strong><small>${profile.star.quadrant} · ${profile.star.animal}</small></article><article class="metric-card"><span class="metric-label">生日节令</span><strong>${profile.solarTerm.name}</strong><small>${profile.solarTerm.theme}</small></article><article class="metric-card"><span class="metric-label">日志记录</span><strong>${journalCount}</strong><small>${journalCount ? '继续回看你的变化' : '写下第一条记录'}</small></article></section><section class="dashboard-grid"><article class="dashboard-pan-card"><div class="card-toolbar"><div><div class="card-kicker">个人总盘 <span>可拖动 · 可下钻</span></div><h3>你的关系图谱</h3></div><div class="dominant-chip" style="color:${profile.dominant.color};border-color:${profile.dominant.color}"><span style="background:${profile.dominant.color}"></span>${profile.dominant.label}相生</div></div><div class="pan-layout"><div class="pan-stage">${panGraphic()}<p class="pan-hint">↔ 拖动盘面 · 点击盘钉查看模块</p></div><div class="pan-legend"><div class="legend-intro"><span class="legend-number">01</span><p>先从一个关系开始。璇玑把复杂的文化资料压缩成可以观察、可以记录的几个入口。</p></div><button class="module-link" data-detail="命盘"><span><b>三柱命盘</b><small>出生日期的时间标记</small></span><i>→</i></button><button class="module-link" data-detail="五行"><span><b>五行气象</b><small>颜色和比例的视觉关系</small></span><i>→</i></button><button class="module-link" data-detail="命纹"><span><b>命纹印章</b><small>为这次输入生成图腾</small></span><i>→</i></button></div></div></article><aside class="dashboard-rail"><article class="insight-card"><div class="card-kicker">今日提示 <span>不作预测</span></div><div class="insight-mark">◇</div><h3>${journalPrompt()}</h3><p>把它写进日志，连续几天后再回来看看。</p><button class="text-button" data-screen="today">开始今日记录 <span>→</span></button></article><article class="dashboard-card module-card"><div class="card-kicker">更多入口 <span>可随时修改</span></div><button class="compact-link" data-detail="星官"><span>本命星官</span><small>${profile.star.name}宿 · ${profile.star.animal}</small><i>→</i></button><button class="compact-link" data-detail="性格"><span>阴阳四维</span><small>用滑条描述此刻状态</small><i>→</i></button><button class="compact-link" data-detail="节气"><span>生日节气</span><small>${profile.solarTerm.name} · 查看时令</small><i>→</i></button></article></aside></section><section class="workspace-note"><span class="status-dot"></span><p><b>本机已保存</b> · 你的观盘和日志保存在这台电脑，不上传服务器。<button class="footer-link" data-screen="info">查看数据边界</button></p></section></main>`); bindDetailTriggers(); bindPanDrag() }
function shareSvg() { const color = profile.dominant.color; const safeName = escapeHtml(profile.name); return `<svg xmlns="http://www.w3.org/2000/svg" width="900" height="1200" viewBox="0 0 900 1200"><rect width="900" height="1200" fill="#172027"/><rect x="30" y="30" width="840" height="1140" fill="none" stroke="${color}" stroke-opacity=".42"/><text x="70" y="85" fill="#7f938d" font-family="monospace" font-size="18">璇玑 / DIGITAL OBSERVATORY</text><text x="830" y="85" text-anchor="end" fill="#7f938d" font-family="monospace" font-size="18">NO. 01</text><circle cx="450" cy="555" r="280" fill="none" stroke="${color}" stroke-width="5" stroke-dasharray="3 14"/><polygon points="${createPattern(profile).split(' ').map((point) => { const [x, y] = point.split(',').map(Number); return `${450 + (x - 50) * 4},${555 + (y - 50) * 4}` }).join(' ')}" fill="none" stroke="${color}" stroke-width="4"/><text x="450" y="820" text-anchor="middle" fill="#f1ede2" font-family="serif" font-size="38">${safeName}</text><text x="450" y="890" text-anchor="middle" fill="${color}" font-family="serif" font-size="34">${profile.pillars.map((p) => p.value).join(' · ')}</text><text x="450" y="940" text-anchor="middle" fill="#a6aaa3" font-family="monospace" font-size="18">主色 / ${profile.dominant.label} · 命纹 / 已落座</text><text x="450" y="980" text-anchor="middle" fill="#a6aaa3" font-family="monospace" font-size="16">星官 / ${profile.star.name} · 节气 / ${profile.solarTerm.name}</text><text x="450" y="1110" text-anchor="middle" fill="#7f938d" font-family="monospace" font-size="16">传统文化可视化体验 · 仅供娱乐</text></svg>` }
function downloadShareSvg() { const blob = new Blob([shareSvg()], { type: 'image/svg+xml;charset=utf-8' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `xuanji-${profile.dateValue}.svg`; document.body.appendChild(link); link.click(); setTimeout(() => { URL.revokeObjectURL(link.href); link.remove() }, 1000) }
function showShare() {
  const safeName = escapeHtml(profile.name)
  const previousFocus = document.activeElement
  const modal = document.createElement('div')
  modal.className = 'modal-backdrop'
  modal.innerHTML = `<div class="share-modal" role="dialog" aria-modal="true" aria-labelledby="share-title"><button class="modal-close" aria-label="关闭分享卡">×</button><p class="eyebrow" id="share-title">铭 · 分享卡</p><div class="share-preview"><div class="share-top"><span>璇玑 / DIGITAL OBSERVATORY</span><span>NO. 01</span></div><div class="share-seal"><svg viewBox="0 0 200 200"><circle cx="100" cy="100" r="76" fill="none" stroke="${profile.dominant.color}" stroke-width="2" stroke-dasharray="2 6"/><polygon points="${createPattern(profile)}" fill="none" stroke="${profile.dominant.color}" stroke-width="1.6"/></svg><span>${safeName}</span></div><div class="share-meta"><b>${profile.pillars.map(p => p.value).join(' · ')}</b><span>主色 / ${profile.dominant.label} · 命纹 / 已落座</span><span>星官 / ${profile.star.name} · 节气 / ${profile.solarTerm.name}</span></div><div class="share-footer">传统文化可视化体验 · 仅供娱乐</div></div><div class="share-actions"><button class="primary-button copy-share" aria-live="polite">复制分享摘要 <span>↗</span></button><button class="ghost-button download-share">下载SVG卡片</button><button class="ghost-button print-share">打印 / 保存图片</button></div><p class="modal-note">SVG可以继续编辑或转换为PNG；打印路径适合快速保存。</p></div>`
  document.body.appendChild(modal)
  const dialog = modal.querySelector('.share-modal')
  const closeButton = modal.querySelector('.modal-close')
  const focusable = () => [...dialog.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])')]
  const closeModal = () => {
    modal.remove()
    if (previousFocus && typeof previousFocus.focus === 'function') previousFocus.focus()
  }
  closeButton.onclick = closeModal
  modal.onclick = (event) => { if (event.target === modal) closeModal() }
  modal.onkeydown = (event) => {
    if (event.key === 'Escape') { event.preventDefault(); closeModal(); return }
    if (event.key !== 'Tab') return
    const items = focusable()
    if (!items.length) return
    const first = items[0]
    const last = items[items.length - 1]
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() }
  }
  closeButton.focus()
  modal.querySelector('.copy-share').onclick = async () => {
    const button = modal.querySelector('.copy-share')
    try {
      await navigator.clipboard.writeText(`我是${profile.name}，我的璇玑主色是${profile.dominant.label}，星官是${profile.star.name}，生日节气是${profile.solarTerm.name}。`)
      button.firstChild.textContent = '已复制摘要'
    } catch {
      button.firstChild.textContent = '请手动复制页面文字'
    }
  }
  modal.querySelector('.download-share').onclick = downloadShareSvg
  modal.querySelector('.print-share').onclick = () => window.print()
}
function reset() { profile = null; localStorage.removeItem('xuanji-profile'); screen = 'home'; render() }
function render() { if (screen !== 'info') infoNotice = ''; if (screen === 'home') home(); else if (screen === 'input') input(); else if (screen === 'detail') detail(); else if (screen === 'info') info(); else if (screen === 'journal') journal(); else if (screen === 'compare') compare(); else if (screen === 'review') review(); else if (screen === 'today') today(); else pan() }
try { const saved = localStorage.getItem('xuanji-profile'); if (saved) { const parsed = JSON.parse(saved); const migrated = parsed?.dateValue ? calculateProfile(parsed.name || '', parsed.dateValue) : null; if (migrated) { migrated.traits = normalizeTraits(parsed.traits); localStorage.setItem('xuanji-profile', JSON.stringify(migrated)) }; profile = migrated; screen = profile ? 'today' : 'home' } } catch { localStorage.removeItem('xuanji-profile') }
render()


